package com.zbw3790.streamdiscs.core;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

/** Fake monotonic timestamps exercise the production barrier and snapshot guard. */
class PreparationTest {
    final UUID a=UUID.randomUUID(),b=UUID.randomUUID(),late=UUID.randomUUID();final long t=900_000_000_000L;
    PreparationBarrier barrier(){return new PreparationBarrier(t,List.of(a,b));}
    void ready(PreparationBarrier p,UUID id,long sequence){assertTrue(p.acknowledge(id,1,sequence,PreparationBarrier.Status.READY));}
    @Test void earlyAndDuplicateCommit(){var p=barrier();ready(p,a,1);assertFalse(p.commit(t+100_000_000L));ready(p,b,1);assertTrue(p.commit(t+400_000_000L));assertEquals(t+600_000_000L,p.anchor());assertFalse(p.commit(t+3_000_000_000L));assertFalse(p.acknowledge(a,2,2,PreparationBarrier.Status.NOT_READY));assertEquals(t+600_000_000L,p.anchor());}
    @Test void nearThreeSecondsIncludesGap(){var p=barrier();ready(p,a,1);ready(p,b,1);assertTrue(p.commit(t+3_000_000_000L));assertEquals(t+3_200_000_000L,p.anchor());}
    @Test void deadlineWithoutAnyReadyAndLateScheduler(){var p=barrier();assertFalse(p.commit(t+3_799_999_999L));assertTrue(p.commit(t+3_800_000_000L));assertEquals(t+4_000_000_000L,p.anchor());var late=barrier();assertTrue(late.commit(t+5_000_000_000L));assertEquals(t+4_000_000_000L,late.anchor());}
    @Test void emptySetAndOnlyRemovalIncludingReconnect(){var empty=new PreparationBarrier(t,List.of());assertTrue(empty.commit(t));assertEquals(t+200_000_000L,empty.anchor());var p=barrier();ready(p,a,1);assertFalse(p.acknowledge(late,1,1,PreparationBarrier.Status.READY));assertTrue(p.retain(List.of(a,late)));assertEquals(Set.of(a),p.members());assertTrue(p.commit(t));assertEquals(t+200_000_000L,p.anchor());}
    @Test void revokedReadyAndAttemptsAreOrdered(){var p=barrier();ready(p,a,1);assertTrue(p.acknowledge(a,1,3,PreparationBarrier.Status.NOT_READY));assertFalse(p.acknowledge(a,1,2,PreparationBarrier.Status.READY));ready(p,b,1);assertFalse(p.commit(t));assertTrue(p.acknowledge(a,2,1,PreparationBarrier.Status.NOT_READY));assertFalse(p.acknowledge(a,1,99,PreparationBarrier.Status.READY));assertTrue(p.acknowledge(a,2,2,PreparationBarrier.Status.READY));assertTrue(p.commit(t));}
    @Test void declinedAndMalformedReceipts(){var p=barrier();assertFalse(p.acknowledge(a,0,1,PreparationBarrier.Status.READY));assertFalse(p.acknowledge(a,1,0,PreparationBarrier.Status.READY));assertFalse(p.acknowledge(a,33,1,PreparationBarrier.Status.READY));assertFalse(p.acknowledge(a,1,1_000_000_001L,PreparationBarrier.Status.READY));ready(p,a,1);assertTrue(p.acknowledge(b,1,1,PreparationBarrier.Status.DECLINED));assertTrue(p.commit(t));}
    @Test void sameInstantDeadlineWinsAndNeverRestarts(){var p=barrier();ready(p,a,1);ready(p,b,1);assertTrue(p.commit(t+3_900_000_000L));assertEquals(t+4_000_000_000L,p.anchor());assertFalse(p.retain(List.of()));assertEquals(2,p.members().size());}
    @Test void fullSnapshotsMonotonicAndCommittedAnchorImmutable(){var id=UUID.randomUUID();var p=new PreparationState(id,10,t,t+4_000_000_000L);assertTrue(p.accept(id,10,t,t+4_000_000_000L,10,PreparationState.Phase.PREPARING,null));assertFalse(p.accept(id,10,t,t+4_000_000_000L,10,PreparationState.Phase.SCHEDULED,t+1_000_000_000L));assertTrue(p.accept(id,10,t,t+4_000_000_000L,11,PreparationState.Phase.SCHEDULED,t+1_000_000_000L));assertTrue(p.accept(id,10,t,t+4_000_000_000L,11,PreparationState.Phase.SCHEDULED,t+1_000_000_000L));assertTrue(p.accept(id,10,t,t+4_000_000_000L,12,PreparationState.Phase.PLAYING,t+1_000_000_000L));assertFalse(p.accept(id,10,t,t+4_000_000_000L,13,PreparationState.Phase.PREPARING,null));assertFalse(p.accept(id,10,t,t+4_000_000_000L,13,PreparationState.Phase.PLAYING,t+2_000_000_000L));assertFalse(p.accept(UUID.randomUUID(),10,t,t+4_000_000_000L,14,PreparationState.Phase.PLAYING,t+1_000_000_000L));assertFalse(p.accept(id,11,t,t+4_000_000_000L,14,PreparationState.Phase.PLAYING,t+1_000_000_000L));var late=new PreparationState(id,10,t,t+4_000_000_000L);assertTrue(late.accept(id,10,t,t+4_000_000_000L,12,PreparationState.Phase.PLAYING,t+1_000_000_000L));}
}
